// MARK: - StopCommand
public struct StopCommand: Codable, Equatable, Sendable {
    public let cmd: StopCommandCmd
    public let meetingId: String

    public enum CodingKeys: String, CodingKey {
        case cmd = "cmd"
        case meetingId = "meetingId"
    }

    public init(cmd: StopCommandCmd, meetingId: String) {
        self.cmd = cmd
        self.meetingId = meetingId
    }
}

// MARK: StopCommand convenience initializers and mutators

public extension StopCommand {
    init(data: Data) throws {
        self = try newJSONDecoder().decode(StopCommand.self, from: data)
    }

    init(_ json: String, using encoding: String.Encoding = .utf8) throws {
        guard let data = json.data(using: encoding) else {
            throw NSError(domain: "JSONDecoding", code: 0, userInfo: nil)
        }
        try self.init(data: data)
    }

    init(fromURL url: URL) throws {
        try self.init(data: try Data(contentsOf: url))
    }

    func with(
        cmd: StopCommandCmd? = nil,
        meetingId: String? = nil
    ) -> StopCommand {
        return StopCommand(
            cmd: cmd ?? self.cmd,
            meetingId: meetingId ?? self.meetingId
        )
    }

    func jsonData() throws -> Data {
        return try newJSONEncoder().encode(self)
    }

    func jsonString(encoding: String.Encoding = .utf8) throws -> String? {
        return String(data: try self.jsonData(), encoding: encoding)
    }
}

public enum StopCommandCmd: String, Codable, Equatable, Sendable {
    case stop = "stop"
}

